import{_ as e,g as r,h as i,A as t}from"./chunks/framework.5DsgHIqL.js";const f=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[],"relativePath":"api/advanced/Overview.md","filePath":"api/advanced/Overview.md","lastUpdated":1789700916000}'),o={name:"api/advanced/Overview.md"};function n(l,a,s,d,p,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>借助AirScript的高级服务，开发者只需要完成较少设置，即可连接到某些公开的金山文档API。 它们的使用方式与AirScript脚本的内置函数十分相似。</p><p>AirScript在运行时会自动处理<a href="#授权流程">授权流程</a>。 不过开发者必须<a href="#启用高级服务">启用高级服务</a>，才能在脚本中使用该服务，若跳过该步骤，会因为找不到该服务而抛出<strong>undefined</strong>错误。</p><h2 id="启用高级服务" tabindex="-1">启用高级服务 <a class="header-anchor" href="#启用高级服务" aria-label="Permalink to &quot;启用高级服务&quot;">​</a></h2><p>要使用高级服务，请按以下说明操作：</p><ol><li>打开<strong>效率</strong>-<strong>AirScript编辑工具</strong>弹出编辑页面。</li><li>点击AirScript编辑工具上方的<strong>服务</strong>。</li><li>点击<strong>添加服务</strong>。</li><li>选择一项服务，然后点击<strong>确认</strong>。</li></ol><p>启用高级服务后，该服务会在自动补全中显示。</p><h2 id="授权流程" tabindex="-1">授权流程 <a class="header-anchor" href="#授权流程" aria-label="Permalink to &quot;授权流程&quot;">​</a></h2><p>AirScript需要用户授权才能访问高级服务中的私密数据。</p><h3 id="授予运行权限" tabindex="-1">授予运行权限 <a class="header-anchor" href="#授予运行权限" aria-label="Permalink to &quot;授予运行权限&quot;">​</a></h3><p>AirScript会根据开发者编写脚本时启用高级服务的配置内容来确定授权范围 （例如访问指定文件或访问网络）。如果脚本需要授权，用户在运行脚本时会弹出授权对话框。 描述这个脚本涉及到的授权范围。</p><p>普通的代码更改并不会清空用户对脚本的授权。但如果开发者对更改了高级服务的配置（新增，修改或删除）， 那用户对脚本的授权也会清空，再次运行脚本时会重新触发授权流程。</p><p><strong>注意</strong>:<strong>我的脚本</strong>中的脚本的所有权完全归属于用户本身，该分类运行脚本时无需触发授权流程。</p><h3 id="取消授权" tabindex="-1">取消授权 <a class="header-anchor" href="#取消授权" aria-label="Permalink to &quot;取消授权&quot;">​</a></h3><p>用户可以对已授权的脚本手动取消授权，请按以下说明操作</p><ol><li>打开<strong>效率</strong>-<strong>AirScript编辑工具</strong>弹出编辑页面。</li><li>找到文件共享脚本下的想取消授权的脚本，点击 <strong>…</strong> 显示更多操作。</li><li>点击<strong>取消服务授权</strong></li></ol><h2 id="使用限制" tabindex="-1">使用限制 <a class="header-anchor" href="#使用限制" aria-label="Permalink to &quot;使用限制&quot;">​</a></h2><p>为防止向用户提供恶意的脚本，出于安全性考虑，使用高级服务存在一些限制。</p><ul><li>过于高频地使用高级服务，当出现这种情况时，脚本的运行会抛出明显的错误通知用户异常调用。</li><li>使用<a href="/docs/api/advanced/HTTP.html">HTTP</a>服务时，禁止使用IP地址发起请求，禁止使用端口发起请求。</li><li>使用<a href="/docs/api/advanced/HTTP.html">HTTP</a>服务时，收到内容的消息体最大为2M，超过2M会抛出错误。</li><li>使用<a href="/docs/api/advanced/KSDrive.html#openfile-openinfo">KSDrive.openFile</a> 获得的<a href="/docs/api/advanced/KSDrive.html#file">File</a>对象没有调用close, 就再次使用<a href="/docs/api/advanced/KSDrive.html#openfile-openinfo">KSDrive.openFile</a> 会报错。</li></ul>',19)])])}const g=e(o,[["render",n]]);export{f as __pageData,g as default};
